        /* 进度条容器 */
        .progress-container {
            width: 100%;
            height: 3px;
            background-color: #403e3e;
            margin-bottom: 16px;
        }

        /* 进度条 - 动态宽度 */
        .progress-bar {
            height: 3px;
            background-color: #d19a66;
            width: 0%;
            transition: width 0.1s ease;
        }

        /* 导航菜单 */
        .nav-menu {
            display: flex;
            gap: 24px;
            margin: 0;
            padding: 0;
        }

        .nav-link {
            padding: 4px 0;
            text-decoration: none;
            color: rgba(255, 255, 255, 0.7);
            font-size: 0.9rem;
            font-weight: 650;
            transition: all 0.2s ease;
            letter-spacing: 0.5px;
            border-bottom: 1px solid transparent;
        }

        .nav-link:hover {
            color: #d19a66;
        }

        .nav-link.active {
            color: #d19a66;
            border-bottom-color: #d19a66;
        }

        /* ===== 文章列表 ===== */
        .posts-list {
            list-style: none;
            margin-top: 24px;
        }

        /* 文章项 - 使用flex布局 */
        .post-item {
            display: flex;
            align-items: center;
