                font-size: 0.95rem;
            }
        }
    </style>
</head>
<body>
    <!-- 深色背景容器 -->
    <div class="page-wrapper">
        <div class="main-card">
            <!-- 顶部区域保持不变 -->
            <div class="top-section">
                <div class="site-title">
                    <img src="/images/头像1.png" alt="logo" class="site-logo-img">
                    SYLVIE's Blog
                </div>

                <div class="progress-container">
                    <div class="progress-bar" id="progressBar"></div>
                </div>

                <div class="nav-menu">
                    <a href="/" class="nav-link">首页</a>
                    <a href="/blog-custom.html" class="nav-link active">日志</a>
                    <a href="/categories/" class="nav-link">分类</a>
                    <a href="/guestbook.html" class="nav-link">留言</a>
                </div>
            </div>

            <!-- 文章列表容器 -->
            <main class="posts-list" id="posts-container">
                <div class="loading-state">📚 加载文章中...</div>
            </main>
        </div>
    </div>

    <script>
// ===== 阅读进度条功能 =====
window.addEventListener('scroll', function() {
    const winScroll = document.documentElement.scrollTop;
    const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
    const scrolled = (winScroll / height) * 100;
    document.getElementById('progressBar').style.width = scrolled + '%';
});

// ===== 相对时间格式化函数 =====
function timeAgo(dateString) {
    try {
        const date = new Date(dateString);
        const now = new Date();
        const seconds = Math.floor((now - date) / 1000);
        const minutes = Math.floor(seconds / 60);
        const hours = Math.floor(minutes / 60);
        const days = Math.floor(hours / 24);
        const months = Math.floor(days / 30);
        const years = Math.floor(days / 365);
        if (years > 0) return years + '年前';
        if (months > 0) return months + '个月前';
        if (days > 0) return days + '天前';
        return '今日';
    } catch(e) {
        return '日期未知';
    }
}

// ===== 通过 GitHub GraphQL API 获取评论数 =====
async function fetchCommentCounts() {
    console.log('fetchCommentCounts 开始执行');
    const postItems = document.querySelectorAll('.post-item');
    console.log('找到文章数量:', postItems.length);

    if (!postItems.length) return;

    // GitHub Token
    const token = '';

    // 先获取所有 discussions
    const query = `
    {
      repository(owner: "chu-bao", name: "my-blog-comments") {
        discussions(first: 10) {
          nodes {
            title
            comments {
              totalCount
            }
          }
        }
      }
    }`;

    try {
        console.log('正在获取所有 discussions...');
        const response = await fetch('https://api.github.com/graphql', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ query })
        });

        const data = await response.json();
        console.log('所有 discussions 返回数据:', data);

        if (data?.data?.repository?.discussions?.nodes) {
            const discussions = data.data.repository.discussions.nodes;

            // 为每篇文章查找对应的 discussion
            for (let item of postItems) {
                const link = item.querySelector('.post-title').getAttribute('href');
                const match = link.match(/path=([^&]+)/);
                if (!match) continue;

                const path = decodeURIComponent(match[1]).replace(/^\/+|\/+$/g, '');
                const viewsSpan = item.querySelector('.post-views');

                // 查找标题包含 path 的 discussion
                const discussion = discussions.find(d => d.title && d.title.includes(path));
                const count = discussion?.comments?.totalCount || 0;

                console.log(`${path} 评论数:`, count);

                if (viewsSpan) {
                    viewsSpan.textContent = count;
                }
            }
        }
    } catch (error) {
        console.error('获取评论数失败:', error);
        // 出错时把所有加载中变成 0
        document.querySelectorAll('.post-views').forEach(span => {
            if (span.textContent === '加载中...') {
                span.textContent = '0';
            }
        });
    }
}

// ===== 文章加载功能 =====
(function() {
    const container = document.getElementById('posts-container');
    container.innerHTML = '<div class="loading-state">📚 加载文章中...</div>';

    fetch('/content.json?t=' + Date.now())
        .then(response => {
            if (!response.ok) throw new Error('content.json 不存在');
            return response.json();
        })
        .then(data => {
            console.log('content.json 加载成功，文章数量:', data.length);

            let posts = Array.isArray(data) ? data : (data.posts || []);

            if (posts.length === 0) {
                container.innerHTML = '<div class="empty-state">📭 暂无文章</div>';
                return;
            }

            posts.sort((a, b) => new Date(b.date) - new Date(a.date));

            let html = '';
            posts.forEach((post) => {
                const relativeDate = timeAgo(post.date);   
                const postPath = post.path.startsWith('/') ? post.path : '/' + post.path;
                const link = `/post-template.html?path=${encodeURIComponent(postPath)}`;
                const thumbnail = post.thumbnail || '/images/default-post.jpg';

                html += `
                    <div class="post-item">
                        <div class="post-image">
                            <img src="${thumbnail}" alt="${post.title}" loading="lazy">
                        </div>
                        <div class="post-content">
                            <div class="post-title-row">
                                <a href="${link}" class="post-title">${post.title || '无标题'}</a>
                                <span class="post-views">加载中...</span>
                            </div>
                            <div class="post-footer">
                                <span class="post-date">${relativeDate}</span>
                            </div>
                        </div>
                    </div>
                `;
            });

            container.innerHTML = html;
            console.log('文章列表渲染完成');

            // 调用获取评论数的函数
            console.log('准备获取评论数...');
            fetchCommentCounts();
        })
        .catch(error => {
            console.error('加载失败:', error);
            container.innerHTML = `
                <div class="error-state">
                    <span style="font-size:1.5rem;">⚠️</span>
                    <h3 style="color:#ff6b6b;">加载失败</h3>
                    <p>${error.message}</p>
                </div>
            `;
        });
})();
</script>
</body>
</html>

